-- Restore predictions data from backup CSV (predictions_rows (5).csv)
-- Run this in the Supabase SQL Editor.
--
-- The status column CHECK constraint (migration 002) only allows
-- PENDING/LIVE/WON/LOST, but the live DB used 'SETTLED' as a status.
-- We update the constraint to include it before inserting.
--
-- The match_id FK is dropped before insert because the matches table was
-- also wiped by migration 021 — these are historical records whose fixture
-- rows no longer exist. The FK is NOT re-added so future predictions (which
-- use the UUID team_id / SportMonks fixture_id flow) are unaffected.

ALTER TABLE predictions DROP CONSTRAINT IF EXISTS valid_status;
ALTER TABLE predictions ADD CONSTRAINT valid_status
  CHECK (status IN ('PENDING', 'LIVE', 'WON', 'LOST', 'SETTLED'));

ALTER TABLE predictions DROP CONSTRAINT IF EXISTS predictions_match_id_fkey;

ON CONFLICT (id) DO NOTHING;

-- Verify
SELECT COUNT(*) AS restored_rows FROM predictions;
